/**
 * @summary Create a Stripe Checkout session for a tee order
 */
export const getCreateTeeCheckoutUrl = () => {
  return `/api/tee/checkout`;
};

export const createTeeCheckout = async (
  createTeeCheckoutInput: CreateTeeCheckoutInput,
  options?: RequestInit,
): Promise<CreateTeeCheckout200> => {
  return customFetch<CreateTeeCheckout200>(getCreateTeeCheckoutUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(createTeeCheckoutInput),
  });
};

export const getCreateTeeCheckoutMutationOptions = <
  TError = ErrorType<void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createTeeCheckout>>,
    TError,
    { data: BodyType<CreateTeeCheckoutInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createTeeCheckout>>,
  TError,
  { data: BodyType<CreateTeeCheckoutInput> },
  TContext
> => {
  const mutationKey = ["createTeeCheckout"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createTeeCheckout>>,
    { data: BodyType<CreateTeeCheckoutInput> }
  > = (props) => {
    const { data } = props ?? {};

    return createTeeCheckout(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateTeeCheckoutMutationResult = NonNullable<
  Awaited<ReturnType<typeof createTeeCheckout>>
>;
export type CreateTeeCheckoutMutationBody = BodyType<CreateTeeCheckoutInput>;
export type CreateTeeCheckoutMutationError = ErrorType<void>;

/**
 * @summary Create a Stripe Checkout session for a tee order
 */
export const useCreateTeeCheckout = <
  TError = ErrorType<void>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createTeeCheckout>>,
    TError,
    { data: BodyType<CreateTeeCheckoutInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof createTeeCheckout>>,
  TError,
  { data: BodyType<CreateTeeCheckoutInput> },
  TContext
> => {
  return useMutation(getCreateTeeCheckoutMutationOptions(options));
};

