/**
 * @summary Get a tee order by Stripe Checkout session ID
 */
export const getGetTeeOrderBySessionUrl = (sessionId: string) => {
  return `/api/tee/orders/by-session/${sessionId}`;
};

export const getTeeOrderBySession = async (
  sessionId: string,
  options?: RequestInit,
): Promise<TeeOrder> => {
  return customFetch<TeeOrder>(getGetTeeOrderBySessionUrl(sessionId), {
    ...options,
    method: "GET",
  });
};

export const getGetTeeOrderBySessionQueryKey = (sessionId: string) => {
  return [`/api/tee/orders/by-session/${sessionId}`] as const;
};

export const getGetTeeOrderBySessionQueryOptions = <
  TData = Awaited<ReturnType<typeof getTeeOrderBySession>>,
  TError = ErrorType<void>,
>(
  sessionId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTeeOrderBySession>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetTeeOrderBySessionQueryKey(sessionId);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getTeeOrderBySession>>
  > = ({ signal }) =>
    getTeeOrderBySession(sessionId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!sessionId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getTeeOrderBySession>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetTeeOrderBySessionQueryResult = NonNullable<
  Awaited<ReturnType<typeof getTeeOrderBySession>>
>;
export type GetTeeOrderBySessionQueryError = ErrorType<void>;

/**
 * @summary Get a tee order by Stripe Checkout session ID
 */

export function useGetTeeOrderBySession<
  TData = Awaited<ReturnType<typeof getTeeOrderBySession>>,
  TError = ErrorType<void>,
>(
  sessionId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTeeOrderBySession>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetTeeOrderBySessionQueryOptions(sessionId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
